import std.io

pub type AppError = Failed(String)

record Fetcher { seed: String }

impl Fetcher {
    fn fetch(self) -> Result<String, AppError> {
        return Ok(self.seed)
    }
}

pub fn main() effect io -> Result<(), AppError> {
    let f = Fetcher { seed: "s" }
    let v = f.fetch()?
    io.println("v ${v}")
    return Ok(())
}
